internal static class ErrorFactory
{
    internal static DroidlineException Create(string code, string message, bool? retryable, DroidlineObject fields)
    {
        switch (code)
        {
            case "NOT_FOUND":
                return new NotFoundException(message, retryable ?? true, fields);
            case "AMBIGUOUS":
                return new AmbiguousException(message, retryable ?? false, fields);
            case "NOT_CLICKABLE":
                return new NotClickableException(message, retryable ?? true, fields);
            case "TIMEOUT":
                return new DroidlineTimeoutException(message, retryable ?? true, fields);
            case "NO_ACCESSIBILITY":
                return new NoAccessibilityException(message, retryable ?? false, fields);
            case "NO_IME":
                return new NoImeException(message, retryable ?? false, fields);
            case "NO_PERMISSION":
                return new NoPermissionException(message, retryable ?? false, fields);
            case "APP_NOT_FOUND":
                return new AppNotFoundException(message, retryable ?? false, fields);
            case "ACTIVITY_BLOCKED":
                return new ActivityBlockedException(message, retryable ?? false, fields);
            case "PROXY_FAILED":
                return new ProxyFailedException(message, retryable ?? true, fields);
            case "UNKNOWN_CMD":
                return new UnknownCmdException(message, retryable ?? false, fields);
            case "UNSUPPORTED":
                return new UnsupportedException(message, retryable ?? false, fields);
            case "BAD_ARGS":
                return new BadArgsException(message, retryable ?? false, fields);
            case "DEVICE_NOT_FOUND":
                return new DeviceNotFoundException(message, retryable ?? false, fields);
            case "DEVICE_OFFLINE":
                return new DeviceOfflineException(message, retryable ?? true, fields);
            case "DEVICE_AMBIGUOUS":
                return new DeviceAmbiguousException(message, retryable ?? false, fields);
            case "DEVICE_LEASED":
                return new DeviceLeasedException(message, retryable ?? true, fields);
            case "LEASE_NOT_FOUND":
                return new LeaseNotFoundException(message, retryable ?? false, fields);
            case "NO_FREE_DEVICE":
                return new NoFreeDeviceException(message, retryable ?? true, fields);
            case "OCR_UNAVAILABLE":
                return new OcrUnavailableException(message, retryable ?? false, fields);
            case "AGENT_RESTARTED":
                return new AgentRestartedException(message, retryable ?? true, fields);
            case "UNAUTHORIZED":
                return new UnauthorizedException(message, retryable ?? false, fields);
            case "PAIRING_FAILED":
                return new PairingFailedException(message, retryable ?? false, fields);
            case "INTERNAL":
                return new InternalException(message, retryable ?? false, fields);
            default:
                return new DroidlineException(message, code, retryable ?? false, fields);
        }
    }
}

/// <summary>The chrome.* commands, reached as d.Chrome.</summary>
public sealed class ChromeCommands
{
    private readonly Device _device;

    internal ChromeCommands(Device device)
    {
        _device = device;
    }

    /// <summary>Open a URL in Chrome.</summary>
    /// <param name="url">Address. https:// is added if missing.</param>
    /// <param name="newTab">Open in a new tab. Default: false.</param>
    /// <param name="cancellationToken">Stops waiting for the reply. A command already sent may still run on the phone.</param>
    /// <exception cref="AppNotFoundException">Package is not installed. Similar package names are suggested.</exception>
    /// <example><code>await d.Chrome.GoAsync("naver.com");</code></example>
    public Task<ChromeGoResult> GoAsync(string url, bool? newTab = null, CancellationToken cancellationToken = default)
    {
        var msg = new Params();
        msg.Add("url", url);
        msg.Opt("new_tab", newTab);
        return _device.RunFieldsAsync<ChromeGoResult>("chrome.go", msg, cancellationToken);
    }
}

